DROP TABLE IF EXISTS `mantenimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `mantenimientos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `vehiculo_id` int(11) NOT NULL,
  `sucursal_id` int(11) DEFAULT NULL,
  `tipo` enum('Preventivo','Correctivo') NOT NULL DEFAULT 'Preventivo',
  `titulo` varchar(150) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `costo` decimal(10,2) NOT NULL DEFAULT 0.00,
  `fecha_programada` date NOT NULL,
  `fecha_realizada` date DEFAULT NULL,
  `kilometraje_servicio` int(11) DEFAULT NULL,
  `proveedor` varchar(100) DEFAULT NULL,
  `estado` enum('Programado','En proceso','Completado','Cancelado') NOT NULL DEFAULT 'Programado',
  `observaciones` text DEFAULT NULL,
  `archivo_nombre_original` varchar(255) DEFAULT NULL,
  `archivo_nombre` varchar(255) DEFAULT NULL,
  `archivo_ruta` varchar(255) DEFAULT NULL,
  `archivo_extension` varchar(15) DEFAULT NULL,
  `archivo_mime` varchar(100) DEFAULT NULL,
  `archivo_tamano` bigint(20) unsigned DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_mantenimientos_vehiculo` (`vehiculo_id`),
  CONSTRAINT `fk_mantenimientos_vehiculo` FOREIGN KEY (`vehiculo_id`) REFERENCES `vehiculos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2664 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

